import { describe, it, expect, beforeEach, afterEach, vi, type Mock } from 'vitest';
import { db } from '@reading-advantage/db';
import { users, sessions, accounts } from '@reading-advantage/db/schema';
import { redirect } from 'next/navigation';
import { requireAuth, requireRole, hasRole, getSession } from './server';
import { createSession } from './session';
import type { Session, UserRole } from './types';

type UserRow = typeof users.$inferSelect;

vi.mock('next/navigation', () => ({
  redirect: vi.fn(),
}));

const mockCookies = {
  get: vi.fn(),
  set: vi.fn(),
  delete: vi.fn(),
};

vi.mock('next/headers', () => ({
  cookies: vi.fn(() => mockCookies),
}));

async function cleanupAuthFixtures(): Promise<void> {
  await db.delete(sessions);
  await db.delete(accounts);
  await db.delete(users);
}

function toSessionUser(user: UserRow): Session['user'] {
  return {
    id: user.id,
    name: user.name,
    username: user.username,
    email: user.email,
    // Drizzle users.role widens to include INTERN; this suite only seeds the four
    // local UserRole values so the narrowing cast is safe.
    role: user.role as UserRole,
    image: user.image,
  };
}

describe('Auth Server Helpers', () => {
  let studentUser: UserRow;
  let teacherUser: UserRow;
  let adminUser: UserRow;
  let systemUser: UserRow;

  beforeEach(async () => {
    await cleanupAuthFixtures();

    mockCookies.get.mockReset();
    mockCookies.set.mockReset();
    mockCookies.delete.mockReset();

    [studentUser] = await db
      .insert(users)
      .values({
        id: 'auth-server-student',
        name: 'Student User',
        username: 'student',
        displayUsername: 'Student',
        email: 'student@example.com',
        role: 'STUDENT',
      })
      .returning();

    [teacherUser] = await db
      .insert(users)
      .values({
        id: 'auth-server-teacher',
        name: 'Teacher User',
        username: 'teacher',
        displayUsername: 'Teacher',
        email: 'teacher@example.com',
        role: 'TEACHER',
      })
      .returning();

    [adminUser] = await db
      .insert(users)
      .values({
        id: 'auth-server-admin',
        name: 'Admin User',
        username: 'admin',
        displayUsername: 'Admin',
        email: 'admin@example.com',
        role: 'ADMIN',
      })
      .returning();

    [systemUser] = await db
      .insert(users)
      .values({
        id: 'auth-server-system',
        name: 'System User',
        username: 'system',
        displayUsername: 'System',
        email: 'system@example.com',
        role: 'SYSTEM',
      })
      .returning();

    vi.clearAllMocks();
  });

  afterEach(async () => {
    await cleanupAuthFixtures();
  });

  describe('hasRole', () => {
    it('should return true when user has exact role', () => {
      const session: Session = {
        id: 'test-session',
        userId: studentUser.id,
        expiresAt: new Date(),
        user: toSessionUser(studentUser),
      };

      expect(hasRole(session, 'STUDENT')).toBe(true);
    });

    it('should return true when user has higher role', () => {
      const session: Session = {
        id: 'test-session',
        userId: teacherUser.id,
        expiresAt: new Date(),
        user: toSessionUser(teacherUser),
      };

      expect(hasRole(session, 'STUDENT')).toBe(true);
    });

    it('should return false when user has lower role', () => {
      const session: Session = {
        id: 'test-session',
        userId: studentUser.id,
        expiresAt: new Date(),
        user: toSessionUser(studentUser),
      };

      expect(hasRole(session, 'TEACHER')).toBe(false);
      expect(hasRole(session, 'ADMIN')).toBe(false);
      expect(hasRole(session, 'SYSTEM')).toBe(false);
    });

    it('should enforce role hierarchy correctly', () => {
      const studentSession: Session = {
        id: 'student-session',
        userId: studentUser.id,
        expiresAt: new Date(),
        user: toSessionUser(studentUser),
      };

      expect(hasRole(studentSession, 'STUDENT')).toBe(true);
      expect(hasRole(studentSession, 'TEACHER')).toBe(false);
      expect(hasRole(studentSession, 'ADMIN')).toBe(false);
      expect(hasRole(studentSession, 'SYSTEM')).toBe(false);

      const teacherSession: Session = {
        id: 'teacher-session',
        userId: teacherUser.id,
        expiresAt: new Date(),
        user: toSessionUser(teacherUser),
      };

      expect(hasRole(teacherSession, 'STUDENT')).toBe(true);
      expect(hasRole(teacherSession, 'TEACHER')).toBe(true);
      expect(hasRole(teacherSession, 'ADMIN')).toBe(false);
      expect(hasRole(teacherSession, 'SYSTEM')).toBe(false);

      const adminSession: Session = {
        id: 'admin-session',
        userId: adminUser.id,
        expiresAt: new Date(),
        user: toSessionUser(adminUser),
      };

      expect(hasRole(adminSession, 'STUDENT')).toBe(true);
      expect(hasRole(adminSession, 'TEACHER')).toBe(true);
      expect(hasRole(adminSession, 'ADMIN')).toBe(true);
      expect(hasRole(adminSession, 'SYSTEM')).toBe(false);

      const systemSession: Session = {
        id: 'system-session',
        userId: systemUser.id,
        expiresAt: new Date(),
        user: toSessionUser(systemUser),
      };

      expect(hasRole(systemSession, 'STUDENT')).toBe(true);
      expect(hasRole(systemSession, 'TEACHER')).toBe(true);
      expect(hasRole(systemSession, 'ADMIN')).toBe(true);
      expect(hasRole(systemSession, 'SYSTEM')).toBe(true);
    });
  });

  describe('requireAuth', () => {
    it('should return session when user is authenticated', async () => {
      const session = await createSession(studentUser.id);
      mockCookies.get.mockReturnValue({ value: session.token });

      const result = await requireAuth();
      expect(result.user.id).toBe(session.user.id);
    });

    it('should redirect to /signin when no session', async () => {
      const redirectMock = redirect as unknown as Mock;

      mockCookies.get.mockReturnValue(undefined);
      await expect(requireAuth()).resolves.toBeUndefined();
      expect(redirectMock).toHaveBeenCalledWith('/signin');
    });
  });

  describe('requireRole', () => {
    it('should allow user with required role', async () => {
      const createdSession = await createSession(studentUser.id);
      mockCookies.get.mockReturnValue({ value: createdSession.token });

      const session = await requireRole('STUDENT');

      expect(session.user.id).toBe(studentUser.id);
    });

    it('should allow higher role to access lower role route', async () => {
      const createdSession = await createSession(teacherUser.id);
      mockCookies.get.mockReturnValue({ value: createdSession.token });

      const session = await requireRole('STUDENT');

      expect(session.user.id).toBe(teacherUser.id);
    });

    it('should redirect to role dashboard when user lacks required role', async () => {
      const createdSession = await createSession(studentUser.id);
      const redirectMock = redirect as unknown as Mock;

      mockCookies.get.mockReturnValue({ value: createdSession.token });

      await expect(requireRole('TEACHER')).resolves.toBeUndefined();
      expect(redirectMock).toHaveBeenCalledWith('/student');
    });

    it('should redirect to admin dashboard when admin lacks required role', async () => {
      const createdSession = await createSession(adminUser.id);
      const redirectMock = redirect as unknown as Mock;

      mockCookies.get.mockReturnValue({ value: createdSession.token });

      await expect(requireRole('SYSTEM')).resolves.toBeUndefined();
      expect(redirectMock).toHaveBeenCalledWith('/admin');
    });
  });

  describe('getSession', () => {
    it('should return null when no session exists', async () => {
      mockCookies.get.mockReturnValue(undefined);
      const session = await getSession();
      expect(session).toBeNull();
    });

    it('should return session when user is authenticated', async () => {
      const createdSession = await createSession(studentUser.id);
      mockCookies.get.mockReturnValue({ value: createdSession.token });
      const session = await getSession();

      expect(session?.user.id).toBe(createdSession.user.id);
    });
  });

  describe('Role Routes', () => {
    it('should map roles to correct routes', () => {
      const roleRouteMap = {
        STUDENT: '/student',
        TEACHER: '/teacher',
        ADMIN: '/admin',
        SYSTEM: '/system',
      };

      expect(roleRouteMap.STUDENT).toBe('/student');
      expect(roleRouteMap.TEACHER).toBe('/teacher');
      expect(roleRouteMap.ADMIN).toBe('/admin');
      expect(roleRouteMap.SYSTEM).toBe('/system');
    });
  });

  describe('Permission Scenarios', () => {
    it('should allow teacher to access student routes', () => {
      const teacherSession: Session = {
        id: 'test',
        userId: teacherUser.id,
        expiresAt: new Date(),
        user: toSessionUser(teacherUser),
      };

      expect(hasRole(teacherSession, 'STUDENT')).toBe(true);
    });

    it('should prevent student from accessing teacher routes', () => {
      const studentSession: Session = {
        id: 'test',
        userId: studentUser.id,
        expiresAt: new Date(),
        user: toSessionUser(studentUser),
      };

      expect(hasRole(studentSession, 'TEACHER')).toBe(false);
    });

    it('should allow admin to access all lower level routes', () => {
      const adminSession: Session = {
        id: 'test',
        userId: adminUser.id,
        expiresAt: new Date(),
        user: toSessionUser(adminUser),
      };

      expect(hasRole(adminSession, 'STUDENT')).toBe(true);
      expect(hasRole(adminSession, 'TEACHER')).toBe(true);
      expect(hasRole(adminSession, 'ADMIN')).toBe(true);
    });

    it('should prevent admin from accessing system routes', () => {
      const adminSession: Session = {
        id: 'test',
        userId: adminUser.id,
        expiresAt: new Date(),
        user: toSessionUser(adminUser),
      };

      expect(hasRole(adminSession, 'SYSTEM')).toBe(false);
    });

    it('should allow system user to access all routes', () => {
      const systemSession: Session = {
        id: 'test',
        userId: systemUser.id,
        expiresAt: new Date(),
        user: toSessionUser(systemUser),
      };

      expect(hasRole(systemSession, 'STUDENT')).toBe(true);
      expect(hasRole(systemSession, 'TEACHER')).toBe(true);
      expect(hasRole(systemSession, 'ADMIN')).toBe(true);
      expect(hasRole(systemSession, 'SYSTEM')).toBe(true);
    });
  });

  describe('Edge Cases', () => {
    it('should handle session with null user fields', () => {
      const session: Session = {
        id: 'test',
        userId: 'test',
        expiresAt: new Date(),
        user: {
          id: 'test',
          name: 'Test',
          username: 'test',
          email: null,
          role: 'STUDENT',
          image: null,
        },
      };

      expect(hasRole(session, 'STUDENT')).toBe(true);
    });

    it('should handle session expiration dates correctly', () => {
      const futureExpiry: Session = {
        id: 'test',
        userId: 'test',
        expiresAt: new Date(Date.now() + 86400000),
        user: {
          id: 'test',
          name: 'Test',
          username: 'test',
          email: null,
          role: 'STUDENT',
          image: null,
        },
      };

      expect(hasRole(futureExpiry, 'STUDENT')).toBe(true);

      const pastExpiry: Session = {
        id: 'test',
        userId: 'test',
        expiresAt: new Date(Date.now() - 86400000),
        user: {
          id: 'test',
          name: 'Test',
          username: 'test',
          email: null,
          role: 'STUDENT',
          image: null,
        },
      };

      // hasRole doesn't check expiration — that's validateSession's job
      expect(hasRole(pastExpiry, 'STUDENT')).toBe(true);
    });
  });
});

/**
 * Phase 1 Red-phase tests for the audit retention documentation.
 *
 * Driven by `measure/tracks/audit_log_retention_dsar_20260605/plan.md`
 * Phase 1 task 3 and `spec.md` §FR-1 ("Retention Policy Configuration").
 * The task asks the Green-phase implementer to:
 *
 *   1. Add a package-level `README.md` to `packages/auth/` that
 *      documents the `AUDIT_RETENTION_DAYS` env var, its default
 *      (2557), the minimum (≥ 365) rule, and the FERPA rationale.
 *   2. Add a new compliance doc at `docs/compliance/retention.md`
 *      that explains the retention policy in plain language and
 *      links the auth package's exports back to the policy.
 *
 * This file pins the expected doc surface as Vitest assertions so
 * a regression (or drift back to a missing doc) trips the test
 * runner instead of relying on a doc review. The tests intentionally
 * read the markdown files at runtime — markdown is a deployable
 * artifact, and the only way to enforce "the docs reference the
 * new env var" is to assert on the file contents.
 *
 * What this file pins:
 *   1. `packages/auth/README.md` — must exist, must mention
 *      `AUDIT_RETENTION_DAYS`, must document the default `2557`,
 *      the `.refine` minimum `365`, the FERPA / 7-year rationale,
 *      and the canonical exports `retentionConfigSchema` /
 *      `getRetentionDays`.
 *   2. `docs/compliance/retention.md` — must exist, must describe
 *      the retention window (default 2557 days ≈ 7 years), the
 *      minimum-of-365-days footgun guard, the privileged-role
 *      rationale (FERPA), and cross-reference the auth README.
 *
 * RED expectations (2026-06-06):
 *   - `packages/auth/README.md` does not exist → all 5 file-read
 *     assertions fail (file-exists, AUDIT_RETENTION_DAYS, default
 *     2557, refine 365, exports).
 *   - `docs/compliance/retention.md` does not exist → all 5
 *     file-read assertions fail (file-exists, 2557 / 7-year
 *     mention, 365 footgun mention, FERPA mention, auth README
 *     cross-reference).
 *
 * Test command (targeted, no DB / no network):
 *   cd packages/auth && npx vitest run src/__tests__/phase-1-docs.test.ts
 *
 * Location note: the test is placed at `src/__tests__/` so it
 * picks up the same Vitest auto-discovery pattern that the
 * committed `audit-retention-config.test.ts` uses (no config
 * changes required). The `path` resolution walks 3 levels up from
 * the test file to the workspace root, matching the prior track's
 * `phase-9-docs.test.ts` convention.
 */
import { describe, expect, it } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
// `packages/auth/src/__tests__/phase-1-docs.test.ts` → up 4 levels → workspace root.
const ROOT = join(__dirname, "..", "..", "..", "..");

const AUTH_README_PATH = join(ROOT, "packages", "auth", "README.md");
const RETENTION_DOC_PATH = join(ROOT, "docs", "compliance", "retention.md");

// ---------------------------------------------------------------------------
// Task 3a — packages/auth/README.md documents the retention policy
// ---------------------------------------------------------------------------

describe("Phase 1 — Task 3a: packages/auth/README.md documents the retention policy", () => {
  it("README.md exists at packages/auth/README.md (FR-1 docs surface)", () => {
    expect(
      existsSync(AUTH_README_PATH),
      "Expected packages/auth/README.md to exist — FR-1 requires the auth " +
        "package to document the retention policy alongside its exports.",
    ).toBe(true);
  });

